package com.playwrightplayground.tests.core;

/**
 * A pause between tests, off unless the suite asks for it: -DtestDelay=1000 (milliseconds), or the
 * same in the pom's YOURS settings, once. For a site the team does not own, where a run of hundreds
 * of tests one after another is a burst its owner did not ask for. The first test does not wait.
 */
public final class Pace {
    private static final long DELAY_MS = Long.parseLong(SiteConfig.value("testDelay", "0"));
    private static boolean first = true;

    private Pace() {}

    /** Between two requests of one test (the link report's): waits testDelay. */
    public static void betweenRequests() {
        if (DELAY_MS <= 0) return;
        try {
            Thread.sleep(DELAY_MS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    /** Before each test: waits testDelay, except before the first. */
    public static synchronized void betweenTests() {
        if (first || DELAY_MS <= 0) {
            first = false;
            return;
        }
        try {
            Thread.sleep(DELAY_MS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
